import { fileExtension } from '@nao/shared/attachments';
import readXlsxFile, { readSheetNames } from 'read-excel-file';

import { fetchAttachment } from '@/lib/attachments';
import { parseDelimitedText } from '@/lib/delimited-text';

/** Rows beyond this are dropped: paging through a million of them is slower than the preview is useful. */
export const MAX_PREVIEW_ROWS = 5000;

export interface AttachmentSheet {
	name: string;
	columns: string[];
	rows: Record<string, unknown>[];
	/** True when the sheet has more rows than the preview kept. */
	truncated: boolean;
}

export type AttachmentPreview =
	| { kind: 'table'; sheets: AttachmentSheet[] }
	| { kind: 'text'; content: string }
	| { kind: 'pdf'; blob: Blob }
	| { kind: 'unsupported' };

type PreviewKind = 'table' | 'workbook' | 'text' | 'pdf' | 'unsupported';

const PREVIEW_KINDS: Record<string, PreviewKind> = {
	csv: 'table',
	tsv: 'table',
	xlsx: 'workbook',
	pdf: 'pdf',
	txt: 'text',
	md: 'text',
	json: 'text',
	jsonl: 'text',
	sql: 'text',
	yaml: 'text',
	yml: 'text',
	xml: 'text',
	html: 'text',
};

export const canPreviewAttachment = (fileName: string): boolean => {
	return previewKindOf(fileName) !== 'unsupported';
};

export async function loadAttachmentPreview(path: string): Promise<AttachmentPreview> {
	const kind = previewKindOf(path);
	if (kind === 'unsupported') {
		return { kind: 'unsupported' };
	}

	const blob = await fetchAttachment(path);

	switch (kind) {
		case 'pdf':
			return { kind: 'pdf', blob };
		case 'text':
			return { kind: 'text', content: await blob.text() };
		case 'table':
			return { kind: 'table', sheets: [readDelimitedSheet(path, await blob.text())] };
		case 'workbook':
			return { kind: 'table', sheets: await readWorkbookSheets(blob) };
	}
}

const previewKindOf = (fileName: string): PreviewKind => {
	return PREVIEW_KINDS[fileExtension(fileName)] ?? 'unsupported';
};

const readDelimitedSheet = (path: string, text: string): AttachmentSheet => {
	const delimiter = fileExtension(path) === 'tsv' ? '\t' : undefined;
	return toSheet(path.split('/').pop() ?? path, parseDelimitedText(text, delimiter));
};

const readWorkbookSheets = async (blob: Blob): Promise<AttachmentSheet[]> => {
	const names = await readSheetNames(blob);
	return Promise.all(names.map(async (name) => toSheet(name, await readXlsxFile(blob, { sheet: name }))));
};

/** Reads the first row as the header, the way every spreadsheet tool does. */
function toSheet(name: string, cells: unknown[][]): AttachmentSheet {
	const truncated = cells.length > MAX_PREVIEW_ROWS + 1;
	const [header = [], ...body] = truncated ? cells.slice(0, MAX_PREVIEW_ROWS + 1) : cells;

	const columns = toColumnNames(header, widestRow([header, ...body]));
	const rows = body.map((row) => {
		return Object.fromEntries(columns.map((column, index) => [column, toCellValue(row[index])]));
	});

	return { name, columns, rows, truncated };
}

/** A blank or repeated header cell still needs a name, since the rows are keyed by it. */
function toColumnNames(header: unknown[], width: number): string[] {
	const taken = new Set<string>();

	return Array.from({ length: width }, (_, index) => {
		const base = String(header[index] ?? '').trim() || `Column ${index + 1}`;
		let name = base;
		for (let suffix = 2; taken.has(name); suffix++) {
			name = `${base} (${suffix})`;
		}
		taken.add(name);
		return name;
	});
}

function widestRow(rows: unknown[][]): number {
	return rows.reduce((widest, row) => Math.max(widest, row.length), 0);
}

/** A workbook hands back real dates, which the table renders as text. */
function toCellValue(value: unknown): unknown {
	if (value === undefined) {
		return null;
	}
	return value instanceof Date ? value.toISOString() : value;
}

import { describe, expect, it } from 'vitest';

import { parseDelimitedText } from './delimited-text';

describe('parseDelimitedText', () => {
	it('splits plain comma-separated rows', () => {
		expect(parseDelimitedText('name,amount\nAlpha,12\nBeta,7')).toEqual([
			['name', 'amount'],
			['Alpha', '12'],
			['Beta', '7'],
		]);
	});

	it('keeps delimiters, line breaks and doubled quotes inside a quoted field', () => {
		expect(parseDelimitedText('name,note\n"Alpha, Ltd","said ""hi""\nthen left"')).toEqual([
			['name', 'note'],
			['Alpha, Ltd', 'said "hi"\nthen left'],
		]);
	});

	it('handles CRLF, a lone carriage return and a trailing newline', () => {
		expect(parseDelimitedText('a,b\r\n1,2\r3,4\n')).toEqual([
			['a', 'b'],
			['1', '2'],
			['3', '4'],
		]);
	});

	it('detects the delimiter a European export uses', () => {
		expect(parseDelimitedText('name;amount\nAlpha;12')).toEqual([
			['name', 'amount'],
			['Alpha', '12'],
		]);
	});

	it('uses the given delimiter rather than detecting one', () => {
		expect(parseDelimitedText('name\tnote\nAlpha\ta, b', '\t')).toEqual([
			['name', 'note'],
			['Alpha', 'a, b'],
		]);
	});

	it('keeps empty fields', () => {
		expect(parseDelimitedText('a,b,c\n1,,3')).toEqual([
			['a', 'b', 'c'],
			['1', '', '3'],
		]);
	});

	it('drops the byte order mark a spreadsheet writes', () => {
		expect(parseDelimitedText('\ufeffname\nAlpha')).toEqual([['name'], ['Alpha']]);
	});
});

